let visitas = [];
let id = 1;

function iniciarSesion() {
  const usuario = document.getElementById('usuario').value.trim();
  if (usuario) {
    document.getElementById('loginScreen').style.display = 'none';
    document.getElementById('mainApp').style.display = 'block';
  } else {
    alert('Por favor ingresa tu nombre de usuario');
  }
}

// Maneja el envío del formulario de visitas
document.getElementById('formVisitas').addEventListener('submit', (e) => {
  e.preventDefault();

  const nombre = document.getElementById('nombre').value.trim();
  const telefono = document.getElementById('telefono').value.trim();
  const ciudad = document.getElementById('ciudad').value.trim();
  const genero = document.getElementById('genero').value;

  if (nombre && telefono && ciudad && genero) {
    const visita = { id, nombre, telefono, ciudad, genero };
    visitas.push(visita);
    id++;
    actualizarTabla();
    e.target.reset();
  }
});

// ===== Inserta el logo en pantalla =====
const logoBase64 = "data:image/png;base64data:image/png;base64,"; // Reemplaza con tu base64

const logo = document.createElement("img");
logo.src = logoBase64;
logo.alt = "Logo Cristo La Roca";
logo.className = "logo"; // usa el estilo CSS

// Coloca el logo al inicio dentro de la pantalla del teléfono
const mountPoint = document.querySelector('.screen') || document.body;
mountPoint.prepend(logo);

// Solo controla el margen, no el tamaño (el tamaño se maneja en CSS)
logo.style.display = "block";
logo.style.margin = "0 auto";

// ===== Actualiza la tabla =====
function actualizarTabla() {
  const tbody = document.querySelector('#tablaVisitas tbody');
  tbody.innerHTML = '';
  visitas.forEach((v) => {
    const fila = `
      <tr>
        <td>${v.id}</td>
        <td>${v.nombre}</td>
        <td>${v.telefono}</td>
        <td>${v.ciudad}</td>
        <td>${v.genero}</td>
      </tr>
    `;
    tbody.innerHTML += fila;
  });
}